insert into feedback_forms (id, template_id, stage, version, status, scale_id, definition) values ('fb-cm-v1', 'fb-cm', 'CM', 1, 'published', 'fb3', '{"dimensions":[{"id":"clar","name":"Claredat i explicacions","emoji":"💡"},{"id":"org","name":"Organització","emoji":"🗂️"},{"id":"amb","name":"Ambient i respecte","emoji":"🤝"},{"id":"sup","name":"Suport","emoji":"🤲"},{"id":"mot","name":"Participació i motivació","emoji":"✨"}],"items":[{"id":"clar1","dimensionId":"clar","student":"M’explica les coses perquè les entengui.","teacher":"Explico les coses perquè les entenguin."},{"id":"sup1","dimensionId":"sup","student":"Quan no ho entenc, m’ajuda.","teacher":"Quan no ho entenen, els ajudo."},{"id":"amb1","dimensionId":"amb","student":"M’escolta quan parlo.","teacher":"Escolto l’alumnat quan parla."},{"id":"amb2","dimensionId":"amb","student":"Em sento bé a la seva classe.","teacher":"L’alumnat se sent bé a la meva classe."},{"id":"org1","dimensionId":"org","student":"Sé què he de fer.","teacher":"L’alumnat sap què ha de fer."},{"id":"mot1","dimensionId":"mot","student":"M’agrada aprendre a la seva classe.","teacher":"A l’alumnat li agrada aprendre a la meva classe."}],"open":[{"id":"mantenir","text":"Què t’agrada més de les seves classes?","maxLength":200}]}');
insert into feedback_forms (id, template_id, stage, version, status, scale_id, definition) values ('fb-cs-v1', 'fb-cs', 'CS', 1, 'published', 'fb4', '{"dimensions":[{"id":"clar","name":"Claredat i explicacions","emoji":"💡"},{"id":"org","name":"Organització","emoji":"🗂️"},{"id":"aval","name":"Avaluació i retorn","emoji":"📝"},{"id":"amb","name":"Ambient i respecte","emoji":"🤝"},{"id":"sup","name":"Suport","emoji":"🤲"},{"id":"mot","name":"Participació i motivació","emoji":"✨"}],"items":[{"id":"clar1","dimensionId":"clar","student":"Entenc el que ens explica.","teacher":"L’alumnat entén el que explico."},{"id":"clar2","dimensionId":"clar","student":"Si no ho entenc, m’ho torna a explicar.","teacher":"Si no ho entenen, ho torno a explicar."},{"id":"org1","dimensionId":"org","student":"Sé què he de fer a cada activitat.","teacher":"L’alumnat sap què ha de fer a cada activitat."},{"id":"org2","dimensionId":"org","student":"Les classes estan ben preparades.","teacher":"Les meves classes estan ben preparades."},{"id":"aval1","dimensionId":"aval","student":"Sé com corregirà les feines.","teacher":"Explico com corregiré les feines."},{"id":"aval2","dimensionId":"aval","student":"Els seus comentaris m’ajuden a fer-ho millor.","teacher":"Els meus comentaris ajuden a fer-ho millor."},{"id":"amb1","dimensionId":"amb","student":"A la seva classe ens respectem.","teacher":"A la meva classe ens respectem."},{"id":"amb2","dimensionId":"amb","student":"Em tracta bé.","teacher":"Tracto bé cada alumne."},{"id":"sup1","dimensionId":"sup","student":"Puc demanar ajuda quan la necessito.","teacher":"L’alumnat pot demanar-me ajuda quan la necessita."},{"id":"sup2","dimensionId":"sup","student":"M’ajuda quan alguna cosa em costa.","teacher":"Ajudo quan alguna cosa costa."},{"id":"mot1","dimensionId":"mot","student":"Puc participar i dir el que penso.","teacher":"L’alumnat pot participar i dir el que pensa."},{"id":"mot2","dimensionId":"mot","student":"M’agrada aprendre a la seva classe.","teacher":"A l’alumnat li agrada aprendre a la meva classe."}],"open":[{"id":"mantenir","text":"Què t’agrada de com ens ensenya?","maxLength":250},{"id":"millorar","text":"Què t’ajudaria a aprendre millor?","maxLength":250}]}');
